mapper.select:
SELECT d.*, COALESCE(f.total_file_size, 0) AS total_file_size FROM ds_driver d LEFT JOIN ( SELECT driver_id, SUM(file_size) AS total_file_size FROM ds_driver_file WHERE is_deleted = 0 GROUP BY driver_id ) f ON f.driver_id = d.id WHERE d.is_deleted = 0
AND d.db_type = #{request.dbType}
AND (d.name LIKE CONCAT('%', #{request.keyword}, '%') OR d.driver_class LIKE CONCAT('%', #{request.keyword}, '%'))
ORDER BY ${request.safeSortField()} ${request.safeSortOrder()}
ORDER BY d.create_time DESC
